def compile_mjcf(facts,out):
    pairs=[("center_pedestal","input_bearing","relation/input_bearing_in_pedestal","fit/center_pedestal/input_bearing_seat/input_bearing/outer_race","exclude","Press fit rigid carrying replaces contact."),("input_bearing","input_shaft","relation/input_shaft_lower_journal","fit/input_bearing/shaft_journal/input_shaft/lower_journal","exclude","Running journal replaced by hinge."),("input_shaft","sun_gear","relation/sun_to_input_shaft_press_fit","fit/input_shaft/sun_press_seat/sun_gear/shaft_bore","exclude","Interference press fit rigid carrying replaces contact."),("center_pedestal","carrier_bearing","relation/carrier_bearing_on_pedestal","fit/center_pedestal/carrier_bearing_seat/carrier_bearing/pedestal_bore","keep","Running support fit retained because overlap is uncertain."),("carrier_bearing","carrier","relation/carrier_on_central_bearing","fit/carrier_bearing/carrier_journal/carrier/central_bore","keep","Journal inspected; uncertain overlap retained."),("sun_gear","planet_gear_1","relation/sun_planet_1_mesh","fit/sun_gear/planet_mesh_1/planet_gear_1/sun_mesh","exclude","Exact sun mesh replaced by equality."),("sun_gear","planet_gear_2","relation/sun_planet_2_mesh","fit/sun_gear/planet_mesh_2/planet_gear_2/sun_mesh","exclude","Exact sun mesh replaced by equality."),("sun_gear","planet_gear_3","relation/sun_planet_3_mesh","fit/sun_gear/planet_mesh_3/planet_gear_3/sun_mesh","exclude","Exact sun mesh replaced by equality."),("planet_bushing_1","planet_gear_1","relation/planet_1_bushing_journal","fit/planet_bushing_1/gear_journal/planet_gear_1/bearing_bore","keep","Journal inspected; uncertain overlap retained."),("planet_bushing_2","planet_gear_2","relation/planet_2_bushing_journal","fit/planet_bushing_2/gear_journal/planet_gear_2/bearing_bore","keep","Journal inspected; uncertain overlap retained."),("planet_bushing_3","planet_gear_3","relation/planet_3_bushing_journal","fit/planet_bushing_3/gear_journal/planet_gear_3/bearing_bore","keep","Journal inspected; uncertain overlap retained.")]
    contacts=[]
    for a,b,s,f,act,r in pairs: contacts.append({"pair":[a,b],"action":act,"reason":r,"source_entity_ids":[s],"fact_ids":[s,f,"pair/"+a+"/"+b]})
    for i in (1,2,3): contacts.append({"pair":["fixed_ring_gear","planet_gear_"+str(i)],"action":"exclude","reason":"Exact declared internal planetary tooth mesh replaced by fixed-ring stage equalities.","source_entity_ids":["planetary_stage/four_to_one_planetary_stage","port/planet_gear_"+str(i)+"/ring_mesh","port/fixed_ring_gear/internal_mesh_"+str(i)],"fact_ids":["planetary_stage/four_to_one_planetary_stage","port/planet_gear_"+str(i)+"/ring_mesh","port/fixed_ring_gear/internal_mesh_"+str(i),"fit/planet_gear_"+str(i)+"/ring_mesh/fixed_ring_gear/internal_mesh_"+str(i),"pair/fixed_ring_gear/planet_gear_"+str(i)]})
    cmap={}
    for n in facts["links"]: cmap[n]=None
    for n in ["input_shaft","sun_gear","input_crank","crank_handle"]: cmap[n]="input_shaft_world_hinge"
    for n in ["carrier","output_indicator","planet_pin_1","planet_pin_2","planet_pin_3","planet_bushing_1","planet_bushing_2","planet_bushing_3"]: cmap[n]="carrier_world_hinge"
    for i in (1,2,3): cmap["planet_gear_"+str(i)]="planet_"+str(i)+"_carrier_hinge"
    tree=[("base",""),("center_pedestal","base"),("input_bearing","center_pedestal"),("carrier_bearing","center_pedestal"),("ring_post_1","base"),("ring_post_2","base"),("ring_post_3","base"),("fixed_ring_gear","ring_post_1"),("carrier","fixed_ring_gear"),("input_shaft","carrier"),("sun_gear","input_shaft"),("input_crank","input_shaft"),("crank_handle","input_crank"),("output_indicator","carrier"),("planet_pin_1","carrier"),("planet_bushing_1","planet_pin_1"),("planet_pin_2","carrier"),("planet_bushing_2","planet_pin_2"),("planet_pin_3","carrier"),("planet_bushing_3","planet_pin_3"),("planet_gear_1","carrier"),("planet_gear_2","carrier"),("planet_gear_3","carrier")]
    out.topology_plan({"coordinate_map":cmap,"tree_edges":tree,"closure_edges":["eq_carrier","eq_p1","eq_p2","eq_p3"],"rigid_carried":[["input_shaft","sun_gear"],["input_shaft","input_crank"],["input_crank","crank_handle"],["carrier","output_indicator"],["carrier","planet_pin_1"],["carrier","planet_pin_2"],["carrier","planet_pin_3"],["carrier","planet_bushing_1"],["carrier","planet_bushing_2"],["carrier","planet_bushing_3"]],"independent_coaxial":[["input_shaft","carrier"]],"transmissions":[{"name":"input_shaft_to_sun","ratio":1.0},{"name":"four_to_one_planetary_stage","ratio":0.25}],"contact_decisions":contacts,"support_ground":"base rests on retained ground","support_strategy":"fixed base and ring support nested hinge chain"})
    for n,p in tree:
        out.body(n,p)
        if n=="carrier": out.joint(n,"carrier_world_hinge",axis=(0,0,1),pos_mm=(0,0,0),frame="world")
        if n=="input_shaft": out.joint(n,"input_shaft_world_hinge",axis=(0,0,1),pos_mm=(0,0,0),frame="world")
        if n=="planet_gear_1": out.joint(n,"planet_1_carrier_hinge",axis=(0,0,1),pos_mm=(27,0,0),frame="world")
        if n=="planet_gear_2": out.joint(n,"planet_2_carrier_hinge",axis=(0,0,1),pos_mm=(-13.5,23.3827,0),frame="world")
        if n=="planet_gear_3": out.joint(n,"planet_3_carrier_hinge",axis=(0,0,1),pos_mm=(-13.5,-23.3827,0),frame="world")
    out.joint_equality("eq_carrier","input_shaft_world_hinge","carrier_world_hinge",.333333333333,reason="Nested coordinates yield world carrier at one quarter input.",sources=["planetary_stage/four_to_one_planetary_stage"],fact_ids=["planetary_stage/four_to_one_planetary_stage"])
    for i in (1,2,3): out.joint_equality("eq_p"+str(i),"carrier_world_hinge","planet_"+str(i)+"_carrier_hinge",-3,reason="Fixed-ring local planet spin.",sources=["planetary_stage/four_to_one_planetary_stage","relation/sun_planet_"+str(i)+"_mesh"],fact_ids=["planetary_stage/four_to_one_planetary_stage","relation/sun_planet_"+str(i)+"_mesh"])
    for q in contacts:
        if q["action"]=="exclude": out.exclude(q["pair"][0],q["pair"][1],q["reason"],q["source_entity_ids"],q["fact_ids"])
    for e in facts["entity_ids"]:
        if e[:5]=="link/": out.decision(e,action="emitted",generated_nodes=[e[5:]],reason="Link emitted exactly once.",fact_ids=[e])
        else: out.decision(e,action="represented_by",generated_nodes=["base"],reason="Entity represented by topology, equalities, contacts, or roles.",fact_ids=[e])
